<template>
  <div class="file-upload-container">
    <!-- Input para seleccionar el archivo -->
    <input type="file" @change="handleFileUpload" accept=".zip" class="file-input" />
    
    <!-- Botón para subir el archivo -->
    <button @click="submitFile" :disabled="isLoading" class="upload-button">
      <span v-if="!isLoading && !isCompleted">Subir Archivo</span>
      <span v-if="isLoading">Cargando...</span>
      <span v-if="isCompleted">¡Completado!</span>
    </button>
  </div>
</template>

<script>
export default {
  data() {
    return {
      file: null, // Almacena el archivo seleccionado
      isLoading: false, // Estado de carga
      isCompleted: false, // Estado de completado
    };
  },
  methods: {
    // Maneja la selección del archivo
    handleFileUpload(event) {
      this.file = event.target.files[0];
      this.isCompleted = false; // Reinicia el estado de completado
    },
    // Sube el archivo al backend
    async submitFile() {
      if (!this.file) {
        alert("Por favor, selecciona un archivo ZIP.");
        return;
      }

      this.isLoading = true; // Activa el estado de carga

      const formData = new FormData();
      formData.append("file", this.file);

      try {
        const response = await fetch("http://localhost:5000/upload", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          throw new Error("Error al subir el archivo.");
        }

        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute("download", this.file.name.replace(/\.[^/.]+$/, "_Modificado.xlsx"));
        document.body.appendChild(link);
        link.click();
        link.remove();
        window.URL.revokeObjectURL(url);

        this.isCompleted = true; // Activa el estado de completado
      } catch (error) {
        console.error("Error:", error);
        alert("Hubo un error al procesar el archivo.");
      } finally {
        this.isLoading = false; // Desactiva el estado de carga
      }
    },
  },
};
</script>

